//***********************************************************************
//  Field multiplication in GF(p)
//  Operation: c = a x b mod p
//  Inputs: a stored in [x1], b stored in [x2]
//  Output: c stored in [x0]
//  Register allocation: a (resident) = x3..x14;
//                       acc z0..z12 = x15..x17,x19..x28,
//                       scalar bi = x30, MULADD temp x1;
//                       the reduction borrows bi (dead there).
//***********************************************************************
.global CDECL(fp_mul)
.p2align 6
CDECL(fp_mul):
    stp   x19, x20, [sp, #-96]!
    stp   x21, x22, [sp, #16]
    stp   x23, x24, [sp, #32]
    stp   x25, x26, [sp, #48]
    stp   x27, x28, [sp, #64]
    str   x30, [sp, #80]
    ldp   x3, x4, [x1]
    ldp   x5, x6, [x1, #16]
    ldp   x7, x8, [x1, #32]
    ldp   x9, x10, [x1, #48]
    ldp   x11, x12, [x1, #64]
    ldp   x13, x14, [x1, #80]
    // x15..x17,x19..x28 <- z = a x b0
    ldr   x30, [x2]
    MUL64x768  x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26,x27,x28, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13,x14, x30, x1
    FPMUL768x768  x2, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13,x14, x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26,x27,x28, x30, x1
    // reduce x28,x15..x17,x19..x26 into [0, p)
    mov   x1, #-1
    movn  x30, #0xf5c0, lsl #48      // p[11] = 0x0A3FFFFFFFFFFFFF
    subs  x28, x28, x1
    sbcs  x15, x15, x1
    sbcs  x16, x16, x1
    sbcs  x17, x17, x1
    sbcs  x19, x19, x1
    sbcs  x20, x20, x1
    sbcs  x21, x21, x1
    sbcs  x22, x22, x1
    sbcs  x23, x23, x1
    sbcs  x24, x24, x1
    sbcs  x25, x25, x1
    sbcs  x26, x26, x30
    sbc   x1, xzr, xzr               // mask = -borrow
    and   x30, x30, x1
    adds  x28, x28, x1
    adcs  x15, x15, x1
    adcs  x16, x16, x1
    adcs  x17, x17, x1
    adcs  x19, x19, x1
    adcs  x20, x20, x1
    adcs  x21, x21, x1
    adcs  x22, x22, x1
    adcs  x23, x23, x1
    adcs  x24, x24, x1
    adcs  x25, x25, x1
    adc   x26, x26, x30
    stp   x28, x15, [x0]
    stp   x16, x17, [x0, #16]
    stp   x19, x20, [x0, #32]
    stp   x21, x22, [x0, #48]
    stp   x23, x24, [x0, #64]
    stp   x25, x26, [x0, #80]
    ldr   x30, [sp, #80]
    ldp   x27, x28, [sp, #64]
    ldp   x25, x26, [sp, #48]
    ldp   x23, x24, [sp, #32]
    ldp   x21, x22, [sp, #16]
    ldp   x19, x20, [sp], #96
    ret

//***********************************************************************
//  Field squaring in GF(p): fp_mul with b = a
//***********************************************************************
.global CDECL(fp_sqr)
.p2align 6
CDECL(fp_sqr):
    mov   x2, x1
    b     CDECL(fp_mul)

//***********************************************************************
//  Multiplication in GF(p^2) (Karatsuba, 3 Montgomery multiplications)
//  Operation: c0 = a0 x b0 - a1 x b1 ; c1 = a0 x b1 + a1 x b0
//    as P0 = a0 x b0, P1 = a1 x b1, P2 = (a0+a1) x (b0+b1), each reduced
//    into [0, p), then c0 = P0 - P1 and c1 = P2 - P1 - P0 (mod p).
//    a0+a1 and b0+b1 are kept unreduced (< 2p): P2 < 4p^2/R + p < 2p.
//  Inputs: a = [a0, a1] stored in [x1]
//          b = [b0, b1] stored in [x2]
//  Output: c = [c0, c1] stored in [x0]  (written only after a and b are
//          fully read: c may alias a or b)
//  Register allocation: multiplicand (r/b0/b1 in turn) = x3..x14;
//                       acc z0..z12 = x15..x17,x19..x28,
//                       scalar bi = x30, MULADD temp x0;
//                       scalars (s/a0/a1) streamed from [sp]/[x1].
//  Stack: [sp+0 .. 96) holds s = a0+a1, then P2;
//         [sp+96 .. 192) holds P0.
//***********************************************************************
.global CDECL(fp2_mul)
.p2align 6
CDECL(fp2_mul):
    sub   sp, sp, #304               // 208 for s/P2 + P0 + out + 96 for callee saves
    stp   x19, x20, [sp, #208]
    stp   x21, x22, [sp, #224]
    stp   x23, x24, [sp, #240]
    stp   x25, x26, [sp, #256]
    stp   x27, x28, [sp, #272]
    str   x30, [sp, #288]
    str   x0, [sp, #192]             // spill the out pointer: x0 joins the pool

    // s = a0 + a1 (unreduced, < 2p) -> [sp]
    ldp   x15, x16, [x1]
    ldp   x17, x19, [x1, #16]
    ldp   x20, x21, [x1, #32]
    ldp   x22, x23, [x1, #48]
    ldp   x24, x25, [x1, #64]
    ldp   x26, x27, [x1, #80]
    ldp   x30, x0, [x1, #96]
    adds  x15, x15, x30
    adcs  x16, x16, x0
    ldp   x30, x0, [x1, #112]
    adcs  x17, x17, x30
    adcs  x19, x19, x0
    ldp   x30, x0, [x1, #128]
    adcs  x20, x20, x30
    adcs  x21, x21, x0
    ldp   x30, x0, [x1, #144]
    adcs  x22, x22, x30
    adcs  x23, x23, x0
    ldp   x30, x0, [x1, #160]
    adcs  x24, x24, x30
    adcs  x25, x25, x0
    ldp   x30, x0, [x1, #176]
    adcs  x26, x26, x30
    adc   x27, x27, x0
    stp   x15, x16, [sp]
    stp   x17, x19, [sp, #16]
    stp   x20, x21, [sp, #32]
    stp   x22, x23, [sp, #48]
    stp   x24, x25, [sp, #64]
    stp   x26, x27, [sp, #80]
    // r = b0 + b1 (unreduced, < 2p) -> x3..x14
    ldp   x3, x4, [x2]
    ldp   x5, x6, [x2, #16]
    ldp   x7, x8, [x2, #32]
    ldp   x9, x10, [x2, #48]
    ldp   x11, x12, [x2, #64]
    ldp   x13, x14, [x2, #80]
    ldp   x30, x0, [x2, #96]
    adds  x3, x3, x30
    adcs  x4, x4, x0
    ldp   x30, x0, [x2, #112]
    adcs  x5, x5, x30
    adcs  x6, x6, x0
    ldp   x30, x0, [x2, #128]
    adcs  x7, x7, x30
    adcs  x8, x8, x0
    ldp   x30, x0, [x2, #144]
    adcs  x9, x9, x30
    adcs  x10, x10, x0
    ldp   x30, x0, [x2, #160]
    adcs  x11, x11, x30
    adcs  x12, x12, x0
    ldp   x30, x0, [x2, #176]
    adcs  x13, x13, x30
    adc   x14, x14, x0

    // P2 = r x s -> [sp], overwriting s
    // x15..x17,x19..x28 <- z = a x b0
    ldr   x30, [sp]
    MUL64x768  x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26,x27,x28, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13,x14, x30, x0
    FPMUL768x768  sp, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13,x14, x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26,x27,x28, x30, x0
    // reduce x28,x15..x17,x19..x26 into [0, p)
    mov   x30, #-1
    movn  x0, #0xf5c0, lsl #48       // p[11] = 0x0A3FFFFFFFFFFFFF
    subs  x28, x28, x30
    sbcs  x15, x15, x30
    sbcs  x16, x16, x30
    sbcs  x17, x17, x30
    sbcs  x19, x19, x30
    sbcs  x20, x20, x30
    sbcs  x21, x21, x30
    sbcs  x22, x22, x30
    sbcs  x23, x23, x30
    sbcs  x24, x24, x30
    sbcs  x25, x25, x30
    sbcs  x26, x26, x0
    sbc   x30, xzr, xzr              // mask = -borrow
    and   x0, x0, x30
    adds  x28, x28, x30
    adcs  x15, x15, x30
    adcs  x16, x16, x30
    adcs  x17, x17, x30
    adcs  x19, x19, x30
    adcs  x20, x20, x30
    adcs  x21, x21, x30
    adcs  x22, x22, x30
    adcs  x23, x23, x30
    adcs  x24, x24, x30
    adcs  x25, x25, x30
    adc   x26, x26, x0
    stp   x28, x15, [sp]
    stp   x16, x17, [sp, #16]
    stp   x19, x20, [sp, #32]
    stp   x21, x22, [sp, #48]
    stp   x23, x24, [sp, #64]
    stp   x25, x26, [sp, #80]

    // P0 = b0 x a0 -> [sp+96]
    ldp   x3, x4, [x2]
    ldp   x5, x6, [x2, #16]
    ldp   x7, x8, [x2, #32]
    ldp   x9, x10, [x2, #48]
    ldp   x11, x12, [x2, #64]
    ldp   x13, x14, [x2, #80]
    // x28,x15..x17,x19..x27 <- z = a x b0
    ldr   x30, [x1]
    MUL64x768  x28,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26,x27, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13,x14, x30, x0
    FPMUL768x768  x1, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13,x14, x28,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26,x27, x30, x0
    // reduce x27,x28,x15..x17,x19..x25 into [0, p)
    mov   x30, #-1
    movn  x0, #0xf5c0, lsl #48       // p[11] = 0x0A3FFFFFFFFFFFFF
    subs  x27, x27, x30
    sbcs  x28, x28, x30
    sbcs  x15, x15, x30
    sbcs  x16, x16, x30
    sbcs  x17, x17, x30
    sbcs  x19, x19, x30
    sbcs  x20, x20, x30
    sbcs  x21, x21, x30
    sbcs  x22, x22, x30
    sbcs  x23, x23, x30
    sbcs  x24, x24, x30
    sbcs  x25, x25, x0
    sbc   x30, xzr, xzr              // mask = -borrow
    and   x0, x0, x30
    adds  x27, x27, x30
    adcs  x28, x28, x30
    adcs  x15, x15, x30
    adcs  x16, x16, x30
    adcs  x17, x17, x30
    adcs  x19, x19, x30
    adcs  x20, x20, x30
    adcs  x21, x21, x30
    adcs  x22, x22, x30
    adcs  x23, x23, x30
    adcs  x24, x24, x30
    adc   x25, x25, x0
    stp   x27, x28, [sp, #96]
    stp   x15, x16, [sp, #112]
    stp   x17, x19, [sp, #128]
    stp   x20, x21, [sp, #144]
    stp   x22, x23, [sp, #160]
    stp   x24, x25, [sp, #176]

    // P1 = b1 x a1 -> x27,x28,x15..x17,x19..x25
    ldp   x3, x4, [x2, #96]
    ldp   x5, x6, [x2, #112]
    ldp   x7, x8, [x2, #128]
    ldp   x9, x10, [x2, #144]
    ldp   x11, x12, [x2, #160]
    ldp   x13, x14, [x2, #176]
    add   x1, x1, #96                // a1; a and b are dead after P1
    // x27,x28,x15..x17,x19..x26 <- z = a x b0
    ldr   x30, [x1]
    MUL64x768  x27,x28,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13,x14, x30, x0
    FPMUL768x768  x1, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13,x14, x27,x28,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26, x30, x0
    // reduce x26..x28,x15..x17,x19..x24 into [0, p)
    mov   x30, #-1
    movn  x0, #0xf5c0, lsl #48       // p[11] = 0x0A3FFFFFFFFFFFFF
    subs  x26, x26, x30
    sbcs  x27, x27, x30
    sbcs  x28, x28, x30
    sbcs  x15, x15, x30
    sbcs  x16, x16, x30
    sbcs  x17, x17, x30
    sbcs  x19, x19, x30
    sbcs  x20, x20, x30
    sbcs  x21, x21, x30
    sbcs  x22, x22, x30
    sbcs  x23, x23, x30
    sbcs  x24, x24, x0
    sbc   x30, xzr, xzr              // mask = -borrow
    and   x0, x0, x30
    adds  x26, x26, x30
    adcs  x27, x27, x30
    adcs  x28, x28, x30
    adcs  x15, x15, x30
    adcs  x16, x16, x30
    adcs  x17, x17, x30
    adcs  x19, x19, x30
    adcs  x20, x20, x30
    adcs  x21, x21, x30
    adcs  x22, x22, x30
    adcs  x23, x23, x30
    adc   x24, x24, x0

    // c0 = P0 - P1 -> x3..x14
    ldp   x3, x4, [sp, #96]
    ldp   x5, x6, [sp, #112]
    ldp   x7, x8, [sp, #128]
    ldp   x9, x10, [sp, #144]
    ldp   x11, x12, [sp, #160]
    ldp   x13, x14, [sp, #176]
    movn  x0, #0xf5c0, lsl #48       // p[11] = 0x0A3FFFFFFFFFFFFF
    subs  x3, x3, x26
    sbcs  x4, x4, x27
    sbcs  x5, x5, x28
    sbcs  x6, x6, x15
    sbcs  x7, x7, x16
    sbcs  x8, x8, x17
    sbcs  x9, x9, x19
    sbcs  x10, x10, x20
    sbcs  x11, x11, x21
    sbcs  x12, x12, x22
    sbcs  x13, x13, x23
    sbcs  x14, x14, x24
    sbc   x30, xzr, xzr              // mask = -borrow
    and   x0, x0, x30
    adds  x3, x3, x30
    adcs  x4, x4, x30
    adcs  x5, x5, x30
    adcs  x6, x6, x30
    adcs  x7, x7, x30
    adcs  x8, x8, x30
    adcs  x9, x9, x30
    adcs  x10, x10, x30
    adcs  x11, x11, x30
    adcs  x12, x12, x30
    adcs  x13, x13, x30
    adc   x14, x14, x0
    ldr   x25, [sp, #192]            // out pointer
    stp   x3, x4, [x25]
    stp   x5, x6, [x25, #16]
    stp   x7, x8, [x25, #32]
    stp   x9, x10, [x25, #48]
    stp   x11, x12, [x25, #64]
    stp   x13, x14, [x25, #80]

    // c1 = (P2 - P1) - P0
    ldp   x3, x4, [sp]
    ldp   x5, x6, [sp, #16]
    ldp   x7, x8, [sp, #32]
    ldp   x9, x10, [sp, #48]
    ldp   x11, x12, [sp, #64]
    ldp   x13, x14, [sp, #80]
    movn  x0, #0xf5c0, lsl #48       // p[11] = 0x0A3FFFFFFFFFFFFF
    subs  x3, x3, x26
    sbcs  x4, x4, x27
    sbcs  x5, x5, x28
    sbcs  x6, x6, x15
    sbcs  x7, x7, x16
    sbcs  x8, x8, x17
    sbcs  x9, x9, x19
    sbcs  x10, x10, x20
    sbcs  x11, x11, x21
    sbcs  x12, x12, x22
    sbcs  x13, x13, x23
    sbcs  x14, x14, x24
    sbc   x30, xzr, xzr              // mask = -borrow
    and   x0, x0, x30
    adds  x3, x3, x30
    adcs  x4, x4, x30
    adcs  x5, x5, x30
    adcs  x6, x6, x30
    adcs  x7, x7, x30
    adcs  x8, x8, x30
    adcs  x9, x9, x30
    adcs  x10, x10, x30
    adcs  x11, x11, x30
    adcs  x12, x12, x30
    adcs  x13, x13, x30
    adc   x14, x14, x0
    ldp   x26, x27, [sp, #96]
    ldp   x28, x15, [sp, #112]
    ldp   x16, x17, [sp, #128]
    ldp   x19, x20, [sp, #144]
    ldp   x21, x22, [sp, #160]
    ldp   x23, x24, [sp, #176]
    movn  x0, #0xf5c0, lsl #48       // p[11] = 0x0A3FFFFFFFFFFFFF
    subs  x3, x3, x26
    sbcs  x4, x4, x27
    sbcs  x5, x5, x28
    sbcs  x6, x6, x15
    sbcs  x7, x7, x16
    sbcs  x8, x8, x17
    sbcs  x9, x9, x19
    sbcs  x10, x10, x20
    sbcs  x11, x11, x21
    sbcs  x12, x12, x22
    sbcs  x13, x13, x23
    sbcs  x14, x14, x24
    sbc   x30, xzr, xzr              // mask = -borrow
    and   x0, x0, x30
    adds  x3, x3, x30
    adcs  x4, x4, x30
    adcs  x5, x5, x30
    adcs  x6, x6, x30
    adcs  x7, x7, x30
    adcs  x8, x8, x30
    adcs  x9, x9, x30
    adcs  x10, x10, x30
    adcs  x11, x11, x30
    adcs  x12, x12, x30
    adcs  x13, x13, x30
    adc   x14, x14, x0
    stp   x3, x4, [x25, #96]
    stp   x5, x6, [x25, #112]
    stp   x7, x8, [x25, #128]
    stp   x9, x10, [x25, #144]
    stp   x11, x12, [x25, #160]
    stp   x13, x14, [x25, #176]
    ldr   x30, [sp, #288]
    ldp   x27, x28, [sp, #272]
    ldp   x25, x26, [sp, #256]
    ldp   x23, x24, [sp, #240]
    ldp   x21, x22, [sp, #224]
    ldp   x19, x20, [sp, #208]
    add   sp, sp, #304
    ret

//***********************************************************************
//  Squaring in GF(p^2)
//  Operation: c0 = (a0+a1) x (a0-a1) ; c1 = 2 a0 x a1
//    with a0+a1, a0-a1+p and 2*a0 kept unreduced (< 2p), so both
//    Montgomery products are < 2p before their final reduction.
//  Inputs: a = [a0, a1] stored in [x1]
//  Output: c = [c0, c1] stored in [x0]  (c may alias a)
//  Register allocation: multiplicand (d = a0-a1+p, then a1) = x3..x14;
//                       acc z0..z12 = x15..x17,x19..x28,
//                       scalar bi = x30, MULADD temp x0;
//                       scalars streamed from [sp].
//  Stack: [sp+0 .. 96) holds s = a0+a1;
//         [sp+96 .. 192) holds t = 2*a0.
//***********************************************************************
.global CDECL(fp2_sqr)
.p2align 6
CDECL(fp2_sqr):
    sub   sp, sp, #304               // 208 for s + t + out + 96 for callee saves
    stp   x19, x20, [sp, #208]
    stp   x21, x22, [sp, #224]
    stp   x23, x24, [sp, #240]
    stp   x25, x26, [sp, #256]
    stp   x27, x28, [sp, #272]
    str   x30, [sp, #288]
    str   x0, [sp, #192]             // spill the out pointer: x0 joins the pool

    // t = 2*a0 (unreduced) -> [sp+96] ; a0 stays in x3..x14
    ldp   x3, x4, [x1]
    ldp   x5, x6, [x1, #16]
    ldp   x7, x8, [x1, #32]
    ldp   x9, x10, [x1, #48]
    ldp   x11, x12, [x1, #64]
    ldp   x13, x14, [x1, #80]
    adds  x15, x3, x3
    adcs  x16, x4, x4
    adcs  x17, x5, x5
    adcs  x19, x6, x6
    adcs  x20, x7, x7
    adcs  x21, x8, x8
    adcs  x22, x9, x9
    adcs  x23, x10, x10
    adcs  x24, x11, x11
    adcs  x25, x12, x12
    adcs  x26, x13, x13
    adc   x27, x14, x14
    stp   x15, x16, [sp, #96]
    stp   x17, x19, [sp, #112]
    stp   x20, x21, [sp, #128]
    stp   x22, x23, [sp, #144]
    stp   x24, x25, [sp, #160]
    stp   x26, x27, [sp, #176]
    // s = a0 + a1 (unreduced) -> [sp]
    ldp   x15, x16, [x1, #96]
    ldp   x17, x19, [x1, #112]
    ldp   x20, x21, [x1, #128]
    ldp   x22, x23, [x1, #144]
    ldp   x24, x25, [x1, #160]
    ldp   x26, x27, [x1, #176]
    adds  x15, x15, x3
    adcs  x16, x16, x4
    adcs  x17, x17, x5
    adcs  x19, x19, x6
    adcs  x20, x20, x7
    adcs  x21, x21, x8
    adcs  x22, x22, x9
    adcs  x23, x23, x10
    adcs  x24, x24, x11
    adcs  x25, x25, x12
    adcs  x26, x26, x13
    adc   x27, x27, x14
    stp   x15, x16, [sp]
    stp   x17, x19, [sp, #16]
    stp   x20, x21, [sp, #32]
    stp   x22, x23, [sp, #48]
    stp   x24, x25, [sp, #64]
    stp   x26, x27, [sp, #80]
    // d = a0 - a1 + p (unreduced, in (0, 2p)) -> x3..x14
    ldp   x15, x16, [x1, #96]
    subs  x3, x3, x15
    sbcs  x4, x4, x16
    ldp   x15, x16, [x1, #112]
    sbcs  x5, x5, x15
    sbcs  x6, x6, x16
    ldp   x15, x16, [x1, #128]
    sbcs  x7, x7, x15
    sbcs  x8, x8, x16
    ldp   x15, x16, [x1, #144]
    sbcs  x9, x9, x15
    sbcs  x10, x10, x16
    ldp   x15, x16, [x1, #160]
    sbcs  x11, x11, x15
    sbcs  x12, x12, x16
    ldp   x15, x16, [x1, #176]
    sbcs  x13, x13, x15
    sbcs  x14, x14, x16
    mov   x15, #-1
    movn  x16, #0xf5c0, lsl #48      // p[11] = 0x0A3FFFFFFFFFFFFF
    adds  x3, x3, x15
    adcs  x4, x4, x15
    adcs  x5, x5, x15
    adcs  x6, x6, x15
    adcs  x7, x7, x15
    adcs  x8, x8, x15
    adcs  x9, x9, x15
    adcs  x10, x10, x15
    adcs  x11, x11, x15
    adcs  x12, x12, x15
    adcs  x13, x13, x15
    adc   x14, x14, x16

    // c0 = d x s -> [out] (a0's slot; a1 is still intact if c == a)
    // x15..x17,x19..x28 <- z = a x b0
    ldr   x30, [sp]
    MUL64x768  x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26,x27,x28, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13,x14, x30, x0
    FPMUL768x768  sp, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13,x14, x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26,x27,x28, x30, x0
    // reduce x28,x15..x17,x19..x26 into [0, p)
    mov   x30, #-1
    movn  x0, #0xf5c0, lsl #48       // p[11] = 0x0A3FFFFFFFFFFFFF
    subs  x28, x28, x30
    sbcs  x15, x15, x30
    sbcs  x16, x16, x30
    sbcs  x17, x17, x30
    sbcs  x19, x19, x30
    sbcs  x20, x20, x30
    sbcs  x21, x21, x30
    sbcs  x22, x22, x30
    sbcs  x23, x23, x30
    sbcs  x24, x24, x30
    sbcs  x25, x25, x30
    sbcs  x26, x26, x0
    sbc   x30, xzr, xzr              // mask = -borrow
    and   x0, x0, x30
    adds  x28, x28, x30
    adcs  x15, x15, x30
    adcs  x16, x16, x30
    adcs  x17, x17, x30
    adcs  x19, x19, x30
    adcs  x20, x20, x30
    adcs  x21, x21, x30
    adcs  x22, x22, x30
    adcs  x23, x23, x30
    adcs  x24, x24, x30
    adcs  x25, x25, x30
    adc   x26, x26, x0
    ldr   x30, [sp, #192]            // out pointer
    stp   x28, x15, [x30]
    stp   x16, x17, [x30, #16]
    stp   x19, x20, [x30, #32]
    stp   x21, x22, [x30, #48]
    stp   x23, x24, [x30, #64]
    stp   x25, x26, [x30, #80]

    // c1 = a1 x t -> [out+96]
    ldp   x3, x4, [x1, #96]
    ldp   x5, x6, [x1, #112]
    ldp   x7, x8, [x1, #128]
    ldp   x9, x10, [x1, #144]
    ldp   x11, x12, [x1, #160]
    ldp   x13, x14, [x1, #176]
    add   x1, sp, #96                // x1 is dead after the a1 load: reuse it as the t pointer
    // x28,x15..x17,x19..x27 <- z = a x b0
    ldr   x30, [x1]
    MUL64x768  x28,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26,x27, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13,x14, x30, x0
    FPMUL768x768  x1, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13,x14, x28,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26,x27, x30, x0
    // reduce x27,x28,x15..x17,x19..x25 into [0, p)
    mov   x30, #-1
    movn  x0, #0xf5c0, lsl #48       // p[11] = 0x0A3FFFFFFFFFFFFF
    subs  x27, x27, x30
    sbcs  x28, x28, x30
    sbcs  x15, x15, x30
    sbcs  x16, x16, x30
    sbcs  x17, x17, x30
    sbcs  x19, x19, x30
    sbcs  x20, x20, x30
    sbcs  x21, x21, x30
    sbcs  x22, x22, x30
    sbcs  x23, x23, x30
    sbcs  x24, x24, x30
    sbcs  x25, x25, x0
    sbc   x30, xzr, xzr              // mask = -borrow
    and   x0, x0, x30
    adds  x27, x27, x30
    adcs  x28, x28, x30
    adcs  x15, x15, x30
    adcs  x16, x16, x30
    adcs  x17, x17, x30
    adcs  x19, x19, x30
    adcs  x20, x20, x30
    adcs  x21, x21, x30
    adcs  x22, x22, x30
    adcs  x23, x23, x30
    adcs  x24, x24, x30
    adc   x25, x25, x0
    ldr   x30, [sp, #192]            // out pointer
    stp   x27, x28, [x30, #96]
    stp   x15, x16, [x30, #112]
    stp   x17, x19, [x30, #128]
    stp   x20, x21, [x30, #144]
    stp   x22, x23, [x30, #160]
    stp   x24, x25, [x30, #176]
